# Give existing policy and 404 pages the same public navigation without changing their content.
for file in ['404.html','privacy/index.html','terms/index.html','cookies/index.html','accessibility/index.html','editorial-policy/index.html']:
    p=ROOT/file;s=p.read_text()
    s=s.replace('class="pull-public"','class="pull-public marketing"')
    if '/marketing.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="/marketing.css"><script src="/marketing.js" defer></script></head>')
    s=re.sub(r'<a class="pull-skip".*?</header>',header(''),s,count=1,flags=re.S)
    s=re.sub(r'<footer\b.*?</footer>',FOOTER,s,count=1,flags=re.S)
    p.write_text(s)
